        array("id" => "s1997e13", "season" => 1997, "number" => 13, "name" => "The Train Trick Murder Case", "airdate" => "21 Apr 1997", "runtime" => 30, "rating" => null, "summary" => "Conan's got a maddening new riddle: If a train departs the station at 10:30, and another train arrives at 10:35, how can a man on one train kill a man on the other?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/220/552263.jpg"),
