        array("id" => "s1999e4", "season" => 1999, "number" => 4, "name" => "Magic Lover's Murder Case (Case Part)", "airdate" => "25 Jan 1999", "runtime" => 30, "rating" => null, "summary" => "Kogoro and Conan drop Sonoko and Ran off at meeting full of magicians. On their way home, they learn one of the magicians was murdered and hurry back!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/458/1147014.jpg"),
        array("id" => "s1999e5", "season" => 1999, "number" => 5, "name" => "Magic Lover's Murder Case (Suspicion Part)", "airdate" => "1 Feb 1999", "runtime" => 30, "rating" => null, "summary" => "A strangled body appears in the snow, but there are no footprints around it. Is it magic?! As members of the club search the house, two arrows are shot through windows.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/461/1153508.jpg"),
