        array("id" => "s1999e36", "season" => 1999, "number" => 36, "name" => "The Secret of the Moon, the Star, and the Sun (Part Two)", "airdate" => "18 Oct 1999", "runtime" => 30, "rating" => null, "summary" => "Conan discovers an attic in the house, with a dead body. Another man appears and reveals he has been using the house for counterfeiting.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/524/1310041.jpg"),
        array("id" => "s1999e37", "season" => 1999, "number" => 37, "name" => "The Disappearing Detective Boys Case", "airdate" => "25 Oct 1999", "runtime" => 30, "rating" => null, "summary" => "The Detective Boys are on a camping trip to practice for the school puppet play! However, a serial killer has been spotted not far from the camp!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555420.jpg"),
        array("id" => "s1999e38", "season" => 1999, "number" => 38, "name" => "Tottori Spider Mansion Demon (Case Part)", "airdate" => "1 Nov 1999", "runtime" => 30, "rating" => null, "summary" => "Kogoro and Heiji are both hired to solve a mystery in Tottori. A mansion is supposedly haunted by the Demon Spider God and his first hanging victim has been found.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/525/1313302.jpg"),
        array("id" => "s1999e39", "season" => 1999, "number" => 39, "name" => "Tottori Spider Mansion Demon (Suspicion Part)", "airdate" => "8 Nov 1999", "runtime" => 30, "rating" => null, "summary" => "The Demon Spider God continues to hang people. A note is left saying Kazuha will be hung next, can Conan and Heiji save her in time?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/526/1315438.jpg"),
        array("id" => "s1999e40", "season" => 1999, "number" => 40, "name" => "Tottori Spider Mansion Demon (Resolution Part)", "airdate" => "15 Nov 1999", "runtime" => 30, "rating" => null, "summary" => "The culprit is caught thanks to Conan and Heiji who hung those he blamed for not stopping his girlfriend from hanging herself, but what did the killer miss?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/526/1315730.jpg"),
        array("id" => "s1999e41", "season" => 1999, "number" => 41, "name" => "Venus' Kiss", "airdate" => "22 Nov 1999", "runtime" => 30, "rating" => null, "summary" => "When Mouri visits an aquarium, while watching a play, instead of the actress appearing out of the clam, a body floats up from the water.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555424.jpg"),
        array("id" => "s1999e42", "season" => 1999, "number" => 42, "name" => "The Blind Spot in the Darkness (Part One)", "airdate" => "29 Nov 1999", "runtime" => 30, "rating" => null, "summary" => "While visiting a doctor at his house, a blackout occurs. When the lights come back on, a man is found dead in the bath tub.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/528/1320390.jpg"),
        array("id" => "s1999e43", "season" => 1999, "number" => 43, "name" => "The Blind Spot in the Darkness (Part Two)", "airdate" => "6 Dec 1999", "runtime" => 30, "rating" => null, "summary" => "Conan investigates around the house and finds a timer on the fusebox. Who murdered the doctor?!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/528/1321369.jpg"),
        array("id" => "s1999e44", "season" => 1999, "number" => 44, "name" => "The Revival of the Dying Message (Part One)", "airdate" => "13 Dec 1999", "runtime" => 30, "rating" => null, "summary" => "A woman is found dead at Tropical Land in the woman's bathroom with a dying message: \"S smeared in blood and KIX on her phone\"", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/528/1321949.jpg"),
        array("id" => "s1999e45", "season" => 1999, "number" => 45, "name" => "The Revival of the Dying Message (Part Two)", "airdate" => "13 Dec 1999", "runtime" => 30, "rating" => null, "summary" => "Conan determines the \"S\" was a dying message left by the culprit and \"KIX\" is the real message.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/528/1322320.jpg"),
