    array("number" => 2000, "name" => "#174 - #218", "rating" => null, "episodes" => array(
        array("id" => "s2000e1", "season" => 2000, "number" => 1, "name" => "The Twenty Year Old Murderous Intent: The Symphony Serial Murder Case", "airdate" => "3 Jan 2000", "runtime" => 120, "rating" => null, "summary" => "A man known as the Organizer of the Shadows is shot to death by his three subordinates. Twenty years later, Conan helps Ran and Kogoro solve a puzzle for which the prize is an all-expense-paid trip on a giant boat built for a small number of people. After ele…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/529/1324161.jpg"),
        array("id" => "s2000e2", "season" => 2000, "number" => 2, "name" => "The Man Who Was Killed Four Times", "airdate" => "10 Jan 2000", "runtime" => 30, "rating" => null, "summary" => "It appears that following the murder of Komiyama, three people stepped forward as the murderer. However, which one of the three is the actual murderer? Katsumata Kengo, Niikura Yumiko, and Hoshino Hariyuki all had a motive, and when questioned by the police,…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/530/1325574.jpg"),
        array("id" => "s2000e3", "season" => 2000, "number" => 3, "name" => "Reunion with the Black Organization (Haibara Part)", "airdate" => "17 Jan 2000", "runtime" => 30, "rating" => null, "summary" => "Conan and Haibara see Gin's car while walking home from school and Conan is able to place a tracker on it. Gin discovers the tracker though and suspects that Sherry (Haibara) is still alive.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/467/1168790.jpg"),
        array("id" => "s2000e4", "season" => 2000, "number" => 4, "name" => "Reunion with the Black Organization (Conan Part)", "airdate" => "24 Jan 2000", "runtime" => 30, "rating" => null, "summary" => "A murder occurs at Haido City Hotel. Conan discovers that the Black Organization is responsible – Pisco is there. In the commotion of the murder, Haibara is kidnapped. Can Conan save her before the Black Organization finds her?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/530/1326231.jpg"),
        array("id" => "s2000e5", "season" => 2000, "number" => 5, "name" => "Reunion with the Black Organization (Resolution Part)", "airdate" => "31 Jan 2000", "runtime" => 30, "rating" => null, "summary" => "Haibara is trapped in the same building as Gin and Vodka. Conan is able to help her, but the Black Organization now knows she is alive.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/530/1326424.jpg"),
        array("id" => "s2000e6", "season" => 2000, "number" => 6, "name" => "The Coffee Shop Truck's Wild Entrance Case", "airdate" => "7 Feb 2000", "runtime" => 30, "rating" => null, "summary" => "Conan is at a coffee shop when one man is killed by a truck running through the front. What happened to the other man who was with him?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/532/1332404.jpg"),
        array("id" => "s2000e7", "season" => 2000, "number" => 7, "name" => "The Nocturne of Red Murderous Intent (Part One)", "airdate" => "14 Feb 2000", "runtime" => 30, "rating" => null, "summary" => "A client hires Kogoro to find his wife's stalker. At a party, a blackout occurs and someone attempts to grab the client's wife.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/536/1342271.jpg"),
        array("id" => "s2000e8", "season" => 2000, "number" => 8, "name" => "The Nocturne of Red Murderous Intent (Part Two)", "airdate" => "21 Feb 2000", "runtime" => 30, "rating" => null, "summary" => "Conan discovers Red Nocturne has to do with the impaled man just murdered. Was it the stalker?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/536/1342280.jpg"),
        array("id" => "s2000e9", "season" => 2000, "number" => 9, "name" => "The Big Investigation of the Nine Doors", "airdate" => "28 Feb 2000", "runtime" => 30, "rating" => null, "summary" => "The Detective Boys stumble on an SOS sign. Is it a false alarm or is someone hiding something?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555515.jpg"),
        array("id" => "s2000e10", "season" => 2000, "number" => 10, "name" => "A Dangerous Recipe", "airdate" => "6 Mar 2000", "runtime" => 30, "rating" => null, "summary" => "The Detective Boys stumble on to a receipt with a dangerous combination of items on it. It's up to them to find the culprit in time.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/538/1346478.jpg"),
        array("id" => "s2000e11", "season" => 2000, "number" => 11, "name" => "A Cursed Mask Coldly Laughs", "airdate" => "13 Mar 2000", "runtime" => 60, "rating" => null, "summary" => "Kogoro is invited to a car accident charity, but a message from the Phantom of the Cursed Masks warns them not to go. Why have so many people gathered in one mansion and what do all of the masks mean?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555517.jpg"),
        array("id" => "s2000e12", "season" => 2000, "number" => 12, "name" => "The Murdered Famous Detective (Part One)", "airdate" => "10 Apr 2000", "runtime" => 30, "rating" => null, "summary" => "Kogoro is nearly killed by an arrow while driving. When they arrive at the hotel, a dead actor has just been found!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/540/1351521.jpg"),
        array("id" => "s2000e13", "season" => 2000, "number" => 13, "name" => "The Murdered Famous Detective (Part Two)", "airdate" => "17 Apr 2000", "runtime" => 30, "rating" => null, "summary" => "Several people are staying in the hotel, but Kogoro thinks it is the work of an outsider. Conan discovers what the culprit really did, using a modified crossbow.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/540/1351547.jpg"),
        array("id" => "s2000e14", "season" => 2000, "number" => 14, "name" => "The Unknown Gunshot That Rings in the Dark", "airdate" => "24 Apr 2000", "runtime" => 30, "rating" => null, "summary" => "While Kogoro is at a client's house, the woman is murdered. The suspects are the only other guests in her house: her son, daughter, and the maid.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555520.jpg"),
        array("id" => "s2000e15", "season" => 2000, "number" => 15, "name" => "The Desperate Revival: The Cavern of the Detective Boys", "airdate" => "1 May 2000", "runtime" => 30, "rating" => null, "summary" => "The Detective Boys stumble onto a group of robbers with a dead body while camping. Conan helps the Detective Boys get away, but he is shot in the process!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555521.jpg"),
        array("id" => "s2000e16", "season" => 2000, "number" => 16, "name" => "The Desperate Revival: The Wounded Great Detective", "airdate" => "8 May 2000", "runtime" => 30, "rating" => null, "summary" => "The Detective Boys escaped and helped the police arrest the gang. Conan goes into surgery after being shot, but Ran suspects he really is Shinichi! Haibara helps Conan divert suspicion.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555522.jpg"),
        array("id" => "s2000e17", "season" => 2000, "number" => 17, "name" => "The Desperate Revival: The Third Choice", "airdate" => "15 May 2000", "runtime" => 30, "rating" => null, "summary" => "Heiji helps Shinichi by disguising as him to distract Ran from noticing Conan's identity. Ran is playing the school heroine when a murder at school occurs!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555523.jpg"),
        array("id" => "s2000e18", "season" => 2000, "number" => 18, "name" => "The Desperate Revival: The Black Knight", "airdate" => "22 May 2000", "runtime" => 30, "rating" => null, "summary" => "Shinichi returns to his regular body and appears as the Black Knight to save the case, but collapses from a fever.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/544/1361694.jpg"),
        array("id" => "s2000e19", "season" => 2000, "number" => 19, "name" => "The Desperate Revival: Shinichi's Return", "airdate" => "29 May 2000", "runtime" => 30, "rating" => null, "summary" => "Having returned to his normal body, Shinichi takes Ran out to dinner. Shinichi attempts to make a confession to Ran, but a murder occurs", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555525.jpg"),
        array("id" => "s2000e20", "season" => 2000, "number" => 20, "name" => "The Desperate Revival: The Promised Place", "airdate" => "5 Jun 2000", "runtime" => 30, "rating" => null, "summary" => "Shinichi quickly solves the case, but his body gives out and returns to Conan before he had the chance to confess to Ran.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555526.jpg"),
        array("id" => "s2000e21", "season" => 2000, "number" => 21, "name" => "The Significant Music Box (Part One)", "airdate" => "12 Jun 2000", "runtime" => 30, "rating" => null, "summary" => "Conan begs Haibara for an antidote to return him to his normal body, but it is not permanent. Later, a woman requests Kogoro discover the owner of a music box. When visiting their house, Ran and Haruna see an old man's shadow fly by and someone was attacked!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555529.jpg"),
