        array("id" => "s2000e23", "season" => 2000, "number" => 23, "name" => "The Invisible Weapon, Ran's First Investigation", "airdate" => "26 Jun 2000", "runtime" => 30, "rating" => null, "summary" => "Conan, Ran, and Sonoko are out to eat at a café and befriend a couple. Something seems strange about the couple to Ran, so she goes to visit them and learns something unsettling.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/545/1364626.jpg"),
