        array("id" => "s2000e26", "season" => 2000, "number" => 26, "name" => "Kogoro Mouri, Suspect (Part One)", "airdate" => "17 Jul 2000", "runtime" => 30, "rating" => null, "summary" => "Kogoro, Ran, and Conan are staying at a hotel when they run into Kogoro's estranged wife, Eri Kirisaki. Eri is at the hotel with colleagues of hers. Kogoro is upset seeing Eri around another man and proceeds to get drunk. He is later found in the bed of Eri's…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/546/1366420.jpg"),
        array("id" => "s2000e27", "season" => 2000, "number" => 27, "name" => "Kogoro Mouri, Suspect (Part Two)", "airdate" => "24 Jul 2000", "runtime" => 30, "rating" => null, "summary" => "Prime Suspect, Mouri Kogoro, who was found in the room with a dead body. With the help of Conan, Eri, and the police, they use a trick to lure out the real culprit and clear Kogoro's name.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/546/1366845.jpg"),
        array("id" => "s2000e28", "season" => 2000, "number" => 28, "name" => "The Tenth Passenger (Part One)", "airdate" => "31 Jul 2000", "runtime" => 30, "rating" => null, "summary" => "A man dies right in front of Conan, Kogoro, and Ran while riding on a bus. What does a past murder on the bus have to do with this one?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/405/1014587.jpg"),
        array("id" => "s2000e29", "season" => 2000, "number" => 29, "name" => "The Tenth Passenger (Part Two)", "airdate" => "7 Aug 2000", "runtime" => 30, "rating" => null, "summary" => "A murder from 7 years ago pops up when people who rode on the same bus start being murdered. Can Conan stop the bus before it plunges off a cliff?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/405/1014784.jpg"),
        array("id" => "s2000e30", "season" => 2000, "number" => 30, "name" => "The Black Wings of Icarus (Part One)", "airdate" => "14 Aug 2000", "runtime" => 30, "rating" => null, "summary" => "While at a hotel, Kogoro, Ran, and Conan run into some old acquaintances. While there, an actress is also staying at the hotel, but the next morning she is found hung in her room.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/547/1368952.jpg"),
        array("id" => "s2000e31", "season" => 2000, "number" => 31, "name" => "The Black Wings of Icarus (Part Two)", "airdate" => "21 Aug 2000", "runtime" => 30, "rating" => null, "summary" => "Conan rules out a suicide after seeing the crime scene, but can he find who managed to sneak into the room and kill the actress?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/547/1368954.jpg"),
