        array("id" => "s2000e34", "season" => 2000, "number" => 34, "name" => "The Deduction That Was Too Good", "airdate" => "11 Sep 2000", "runtime" => 30, "rating" => null, "summary" => "While walking home from the bar drunk, Kogoro witnesses a fight between two men. The next day, one of them was murdered and the other begs Kogoro to prove his innocence, but something about his alibi is too perfect.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555549.jpg"),
        array("id" => "s2000e35", "season" => 2000, "number" => 35, "name" => "The Entrance to the Maze: The Anger of the Colossus", "airdate" => "9 Oct 2000", "runtime" => 60, "rating" => null, "summary" => "An opening ceremony for a ropeway built through a giant Goddess Statue on the mountains is being held. After the first ride, tourist company president rides through, he disappears. His body is found dead on the Statue's hand.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555552.jpg"),
        array("id" => "s2000e36", "season" => 2000, "number" => 36, "name" => "The Falling from Mt. Ryujin Case", "airdate" => "16 Oct 2000", "runtime" => 30, "rating" => null, "summary" => "A car is rammed off a mountain and seems like a basic case, but the Detective Boys find a code. Can they solve this while trying to hide the code from Conan?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/555554.jpg"),
        array("id" => "s2000e37", "season" => 2000, "number" => 37, "name" => "The Water Palace of Five Colors Legend (Part One)", "airdate" => "23 Oct 2000", "runtime" => 30, "rating" => null, "summary" => "Kogoro, Ran, and Conan attend a tea meeting at the Aonogi family house in place of Sonoko and her father. Behind the house is a pond that changes colors. When the group crosses the pond to the tearoom on the other side, the headmaster is found hung!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377540.jpg"),
        array("id" => "s2000e38", "season" => 2000, "number" => 38, "name" => "The Water Palace of Five Colors Legend (Part Two)", "airdate" => "30 Oct 2000", "runtime" => 30, "rating" => null, "summary" => "What does the pond have to do with the murder? Conan figures out how the killer hung the victim while not being present.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377929.jpg"),
