        array("id" => "s2002e14", "season" => 2002, "number" => 14, "name" => "The Policeman's Missing Notebook Case", "airdate" => "6 May 2002", "runtime" => 30, "rating" => null, "summary" => "Takagi breaks up a scuffle between a singer and their manager and loses his notebook in the process. Finding it out is not as easy when the Detective Boy's learn of a devious plan at hand.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556724.jpg"),
