        array("id" => "s2002e16", "season" => 2002, "number" => 16, "name" => "English Teacher vs. Great Western Detective (Part Two)", "airdate" => "20 May 2002", "runtime" => 30, "rating" => null, "summary" => "Conan and Heiji have Jodie assist them with the investigation, but they continue their investigation of her on their own.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556727.jpg"),
        array("id" => "s2002e17", "season" => 2002, "number" => 17, "name" => "Hooligan's Labyrinth (Part One)", "airdate" => "27 May 2002", "runtime" => 30, "rating" => null, "summary" => "The group is watching a soccer match between the Tokyo Spirits and Noir. Following the game, a man is found stabbed inside a train.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556728.jpg"),
        array("id" => "s2002e18", "season" => 2002, "number" => 18, "name" => "Hooligan's Labyrinth (Part Two)", "airdate" => "3 Jun 2002", "runtime" => 30, "rating" => null, "summary" => "Haibara is seen watching Higo, a soccer player, who's circumstances mimic her own. When Conan explains the situation, he realizes something about the crime.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556729.jpg"),
        array("id" => "s2002e19", "season" => 2002, "number" => 19, "name" => "The Small Witnesses", "airdate" => "10 Jun 2002", "runtime" => 30, "rating" => null, "summary" => "While playing a horror game in an abandoned house, Ayumi, Mitsuhiko, and Genta realize they are not alone. They overhear two men arguing, then fighting, and one dies. Can Conan get there in time to help them?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556730.jpg"),
        array("id" => "s2002e20", "season" => 2002, "number" => 20, "name" => "The Mystery of the Water-Flowing Stone Garden (Part One)", "airdate" => "17 Jun 2002", "runtime" => 30, "rating" => null, "summary" => "Conan, Ran, and Kogoro attend a dinner party with a company president and various other attendees. The next morning the president is found in the water-stone garden.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556731.jpg"),
        array("id" => "s2002e21", "season" => 2002, "number" => 21, "name" => "The Mystery of the Water-Flowing Stone Garden (Part Two)", "airdate" => "24 Jun 2002", "runtime" => 30, "rating" => null, "summary" => "There are no footprints surrounding the presidents body. Kogoro and Conan differ on how they think the crime occurred.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556732.jpg"),
        array("id" => "s2002e22", "season" => 2002, "number" => 22, "name" => "Chinatown Deja Vu in the Rain (Part One)", "airdate" => "1 Jul 2002", "runtime" => 30, "rating" => null, "summary" => "Coming to a Chinese restaurant, only to realise their coupon doesn't work during holidays, Kogoro, Conan, and Ran are asked to come join the movie crew already sitting there. They were looking for a new young actress for their movie, and their eyes was set on…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556733.jpg"),
        array("id" => "s2002e23", "season" => 2002, "number" => 23, "name" => "Chinatown Deja Vu in the Rain (Part Two)", "airdate" => "8 Jul 2002", "runtime" => 30, "rating" => null, "summary" => "Ran begins to look sick throughout the investigation, her mind is elsewhere. The victim was killed with cyanide, but how? Ran remembers her original meeting with Shuichi Akai.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/222/556735.jpg"),
        array("id" => "s2002e24", "season" => 2002, "number" => 24, "name" => "Shinichi Kudo's New York Case (Case Part)", "airdate" => "15 Jul 2002", "runtime" => 30, "rating" => null, "summary" => "Ran collapses in the Chinese restaurant and begins to dream of her trip to New York City with Shinichi several years prior.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560128.jpg"),
        array("id" => "s2002e25", "season" => 2002, "number" => 25, "name" => "Shinichi Kudo's New York Case (Deduction Part)", "airdate" => "22 Jul 2002", "runtime" => 30, "rating" => null, "summary" => "While attending a play in New York, a murder happens right on stage! A serial killer is also on the loose.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560129.jpg"),
        array("id" => "s2002e26", "season" => 2002, "number" => 26, "name" => "Shinichi Kudo's New York Case (Resolution Part)", "airdate" => "29 Jul 2002", "runtime" => 30, "rating" => null, "summary" => "Ran recalls her first meeting with Shuichi Akai in New York City. Ran and Shinichi encounter the serial killer!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560130.jpg"),
        array("id" => "s2002e27", "season" => 2002, "number" => 27, "name" => "Mitsuhiko's Mystifying Forest (Part One)", "airdate" => "5 Aug 2002", "runtime" => 30, "rating" => null, "summary" => "Mitsuhiko has disappeared! Conan is able to track him to a forest in Gunma, but what is he doing there?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560131.jpg"),
        array("id" => "s2002e28", "season" => 2002, "number" => 28, "name" => "Mitsuhiko's Mystifying Forest (Part Two)", "airdate" => "12 Aug 2002", "runtime" => 30, "rating" => null, "summary" => "Haibara divulges information about APTX 4869 to Conan. Mitsuhiko encounters a serial killer hiding in the forest!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560133.jpg"),
