        array("id" => "s2002e30", "season" => 2002, "number" => 30, "name" => "The Princess of the Solitary Island and the Palace of the Dragon King (Pursuit Part)", "airdate" => "26 Aug 2002", "runtime" => 30, "rating" => null, "summary" => "Heiji and Conan discover clues about a kidnapping while investigating the abandoned house. When the house search is conducted, a loud crash happens!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560136.jpg"),
        array("id" => "s2002e31", "season" => 2002, "number" => 31, "name" => "The Princess of the Solitary Island and the Palace of the Dragon King (Resolution Part)", "airdate" => "2 Sep 2002", "runtime" => 30, "rating" => null, "summary" => "The boat is found destroyed and the captain beaten to death. What does the TV Crew they are with have to do with the kidnapping and this abandoned island?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560137.jpg"),
        array("id" => "s2002e32", "season" => 2002, "number" => 32, "name" => "The Smash of Determination and Love (Part One)", "airdate" => "9 Sep 2002", "runtime" => 30, "rating" => null, "summary" => "Ran and Sonoko find a cell phone with a mysterious message on it for Sonoko. Disguised as Sonoko, Ran goes to meet the mysterious sender and is kidnapped!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/580/1451007.jpg"),
        array("id" => "s2002e33", "season" => 2002, "number" => 33, "name" => "The Smash of Determination and Love (Part Two)", "airdate" => "16 Sep 2002", "runtime" => 30, "rating" => null, "summary" => "Ran manages to leave some clues about her kidnappers. Following the apprehension of two of the criminals, Ran tells the group there was a third!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560139.jpg"),
        array("id" => "s2002e34", "season" => 2002, "number" => 34, "name" => "Houseboat Fishing Shock", "airdate" => "14 Oct 2002", "runtime" => 30, "rating" => null, "summary" => "While watching fireworks from a fish boat restaurant, one of the fisherman falls on another and one gets electrocuted!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560140.jpg"),
