        array("id" => "s2002e36", "season" => 2002, "number" => 36, "name" => "Courtroom Confrontation II: Kisaki vs Kujou (Part Two)", "airdate" => "28 Oct 2002", "runtime" => 30, "rating" => null, "summary" => "Kogoro and Conan are able to find a hole in the testimony! What did the witness hide?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560143.jpg"),
