        array("id" => "s2002e38", "season" => 2002, "number" => 38, "name" => "The Kanmon Strait of Friendship and Murderous Intent (Part Two)", "airdate" => "18 Nov 2002", "runtime" => 30, "rating" => null, "summary" => "The group of friends is discovered to have a sad past. What did the group do to get rid of this man?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/224/560146.jpg"),
