        array("id" => "s2013e17", "season" => 2013, "number" => 17, "name" => "The Window at the Girls' School", "airdate" => "11 May 2013", "runtime" => 30, "rating" => null, "summary" => "Kogoro and Conan investigate in female student suicide, after insist of Sonoko's friend, and yet seems the Window hide a secrets...", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567866.jpg"),
        array("id" => "s2013e18", "season" => 2013, "number" => 18, "name" => "Unbelievable! The Case of the Crashed UFO", "airdate" => "18 May 2013", "runtime" => 30, "rating" => null, "summary" => "Conan and Detective Boys encounter UFO crashed beside riverside, what could be this lead them to.. ?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567867.jpg"),
        array("id" => "s2013e19", "season" => 2013, "number" => 19, "name" => "The Shadow Approaching Haibara's Secret (Part 1)", "airdate" => "8 Jun 2013", "runtime" => 30, "rating" => null, "summary" => "During a camping trip, Haibara and the Detective Boys witness a murder and become trapped in a cabin while hiding from the killer. Conan and Sera realize the children are in danger and begin searching for them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567868.jpg"),
        array("id" => "s2013e20", "season" => 2013, "number" => 20, "name" => "The Shadow Approaching Haibara's Secret (Part 2)", "airdate" => "15 Jun 2013", "runtime" => 30, "rating" => null, "summary" => "Conan and Sera race to rescue Haibara and the Detective Boys as the murderer closes in on them. During the confrontation, Haibara is forced to make a risky decision that could expose her secret.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567869.jpg"),
        array("id" => "s2013e21", "season" => 2013, "number" => 21, "name" => "The Jet-Black Mystery Train (Departure)", "airdate" => "13 Jul 2013", "runtime" => 30, "rating" => null, "summary" => "Conan and his friends board the luxurious Bell Tree Express, where a special mystery game is about to begin. However, the trip takes a dangerous turn as members of the Black Organization secretly make their move.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567870.jpg"),
        array("id" => "s2013e22", "season" => 2013, "number" => 22, "name" => "The Jet-Black Mystery Train (Tunnel)", "airdate" => "20 Jul 2013", "runtime" => 30, "rating" => null, "summary" => "A murder occurs aboard the Bell Tree Express, turning the mystery game into a real investigation. As Conan searches for the killer, the Black Organization continues its hunt for Haibara.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567871.jpg"),
        array("id" => "s2013e23", "season" => 2013, "number" => 23, "name" => "The Jet-Black Mystery Train (Intersection)", "airdate" => "27 Jul 2013", "runtime" => 30, "rating" => null, "summary" => "Conan's investigation into the murder continues as the passengers' secrets and movements begin to intersect. Meanwhile, the Black Organization closes in on Haibara, raising the danger aboard the train.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567872.jpg"),
        array("id" => "s2013e24", "season" => 2013, "number" => 24, "name" => "The Jet-Black Mystery Train (Destination)", "airdate" => "3 Aug 2013", "runtime" => 30, "rating" => null, "summary" => "The case aboard the Bell Tree Express reaches its climax as Conan exposes the truth behind the murder. At the same time, the confrontation over Haibara's identity comes to a head, revealing a carefully planned deception.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567873.jpg"),
        array("id" => "s2013e25", "season" => 2013, "number" => 25, "name" => "Conan in a Locked Room", "airdate" => "10 Aug 2013", "runtime" => 30, "rating" => null, "summary" => "Conan becomes trapped in a locked room while investigating a suspicious case. As he searches for a way out, he must uncover the truth behind the crime before the culprit can escape.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567874.jpg"),
        array("id" => "s2013e26", "season" => 2013, "number" => 26, "name" => "Bourbon Figures It Out", "airdate" => "17 Aug 2013", "runtime" => 30, "rating" => null, "summary" => "Conan and Amuro unravel the trick behind the locked-room murder and identify the culprit. During the investigation, Amuro notices Conan's unusual deductive abilities and becomes increasingly suspicious of him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567875.jpg"),
        array("id" => "s2013e27", "season" => 2013, "number" => 27, "name" => "The Framed Great Detective", "airdate" => "31 Aug 2013", "runtime" => 30, "rating" => null, "summary" => "A former criminal challenges Kogoro just before a man falls to his death, leaving Kogoro convinced that he is responsible. With Kogoro's reputation at risk, Conan sets out to prove the truth behind the apparent accident.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567876.jpg"),
        array("id" => "s2013e28", "season" => 2013, "number" => 28, "name" => "The Man Who Fell Slowly", "airdate" => "7 Sep 2013", "runtime" => 30, "rating" => null, "summary" => "Conan investigates the suspicious death of a man who appears to have fallen from a building in an impossible way. As he examines the evidence, he uncovers the trick behind the victim's unusual fall.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567877.jpg"),
        array("id" => "s2013e29", "season" => 2013, "number" => 29, "name" => "An Unconfirmed Shocking Case", "airdate" => "14 Sep 2013", "runtime" => 30, "rating" => null, "summary" => "Conan investigates a suspicious incident involving a man who appears to have been electrocuted under puzzling circumstances. As the clues come together, he works to determine whether it was an accident or a carefully planned crime.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567878.jpg"),
        array("id" => "s2013e30", "season" => 2013, "number" => 30, "name" => "Everyone Saw (Part 1)", "airdate" => "21 Sep 2013", "runtime" => 30, "rating" => null, "summary" => "A murder takes place in front of several witnesses, yet their accounts of what happened do not seem to match. Conan begins examining the contradictions to uncover how the crime was carried out.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567879.jpg"),
        array("id" => "s2013e31", "season" => 2013, "number" => 31, "name" => "Everyone Saw (Part 2)", "airdate" => "28 Sep 2013", "runtime" => 30, "rating" => null, "summary" => "Conan pieces together the conflicting witness statements and reveals the trick behind the murder. With the truth exposed, he identifies the culprit and explains how everyone was misled.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567880.jpg"),
        array("id" => "s2013e32", "season" => 2013, "number" => 32, "name" => "Heiji Hattori and the Vampire Mansion (1)", "airdate" => "5 Oct 2013", "runtime" => 30, "rating" => null, "summary" => "Conan, Heiji, and their friends visit a mansion surrounded by rumors of a vampire. When a mysterious death occurs, the group begins investigating the eerie secrets hidden within the house.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567881.jpg"),
        array("id" => "s2013e33", "season" => 2013, "number" => 33, "name" => "Heiji Hattori and the Vampire Mansion (2)", "airdate" => "12 Oct 2013", "runtime" => 30, "rating" => null, "summary" => "The investigation at the vampire mansion continues as Conan and Heiji examine the strange circumstances surrounding the death. New clues deepen the mystery and suggest that the mansion's supernatural rumors may be hiding a very human crime.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567882.jpg"),
        array("id" => "s2013e34", "season" => 2013, "number" => 34, "name" => "Heiji Hattori and the Vampire Mansion (3)", "airdate" => "19 Oct 2013", "runtime" => 30, "rating" => null, "summary" => "Conan and Heiji continue unraveling the mansion's mysteries as more suspicious events point toward a carefully planned crime. The suspects' motives and hidden connections begin to come to light.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567883.jpg"),
        array("id" => "s2013e35", "season" => 2013, "number" => 35, "name" => "Heiji Hattori and the Vampire Mansion (4)", "airdate" => "26 Oct 2013", "runtime" => 30, "rating" => null, "summary" => "Conan and Heiji uncover the truth behind the mansion's eerie incidents and reveal the culprit's elaborate tricks. The case concludes as the motives behind the so-called vampire mystery finally come to light.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567884.jpg"),
        array("id" => "s2013e36", "season" => 2013, "number" => 36, "name" => "Dancing Demon at the Noh Mask Mansion (Part 1)", "airdate" => "2 Nov 2013", "runtime" => 30, "rating" => null, "summary" => "Three man gather by a dim candle wearing Noh masks to discuss a murder and the profits/inheritance afterwards. Kogoro visits the Museum of Noh Mask Art and is shown an anonymous death threat.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567886.jpg"),
        array("id" => "s2013e37", "season" => 2013, "number" => 37, "name" => "Dancing Demon at the Noh Mask Mansion (Part 2)", "airdate" => "9 Nov 2013", "runtime" => 30, "rating" => null, "summary" => "Two of the three have been murdered! Who wrote the threatening letter? Kogoro and Conan solve the case!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567887.jpg"),
        array("id" => "s2013e38", "season" => 2013, "number" => 38, "name" => "The Devil's Circuit", "airdate" => "16 Nov 2013", "runtime" => 30, "rating" => null, "summary" => "Kogoro, Ran and Conan are invited to a famous writer's house, who wants to speak with Kogoro. After they spend the night, they awake to the three residents of the house murdered! It appears each one was murdered by a different person!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567888.jpg"),
        array("id" => "s2013e39", "season" => 2013, "number" => 39, "name" => "A Dispute over a Platinum Ticket", "airdate" => "23 Nov 2013", "runtime" => 30, "rating" => null, "summary" => "Conan, Ran, Sonoko, the workers from Marin Coffee, and Haruka Kona look for the missing Masako at her apartment to ask her about the platinum ticket online auction only to find her dead on her apartment floor.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567889.jpg"),
        array("id" => "s2013e40", "season" => 2013, "number" => 40, "name" => "Fire and Water Mystery Tour (Aso Part)", "airdate" => "30 Nov 2013", "runtime" => 30, "rating" => null, "summary" => "In a dark room, a thief is frantically looking through an office for something. When he finds it, he smiles and cut opens a bear. The next day, the Detective Boys went to Kumamoto with Ran and Kogoro for a sightseeing trip. Kumamoto is known as the capital of…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567890.jpg"),
