        array("id" => "s2013e42", "season" => 2013, "number" => 42, "name" => "Sweet and Cold Delivery Service (Part 1)", "airdate" => "14 Dec 2013", "runtime" => 30, "rating" => null, "summary" => "The Detective Boys are playing soccer when they meet a cat who regularly comes to Café Poirot for food. Wanting to see where the cat goes, they follow the cat into a refrigerated delivery truck. But they also discover a body! As they hide in the truck, they l…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567892.jpg"),
        array("id" => "s2013e43", "season" => 2013, "number" => 43, "name" => "Sweet and Cold Delivery Service (Part 2)", "airdate" => "21 Dec 2013", "runtime" => 30, "rating" => null, "summary" => "The Detective Boys continue hiding in the truck, but the it's too cold for them. After one collapses, Conan uses paper to write a message and attaches it to the cat and releases it hoping that Amuro will find it and come help them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/567893.jpg"),
