        array("id" => "s2014e13", "season" => 2014, "number" => 13, "name" => "The Secret of the Statue of Kogoro Mouri", "airdate" => "26 Apr 2014", "runtime" => 30, "rating" => null, "summary" => "After hearing Kataoka scream, Conan, Ran, and Seiya head in the direction of the sound to find Sada holding the deceased Kataoka. It appears Kataoka died after receiving blunt force trauma from falling off a ladder.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/568088.jpg"),
