        array("id" => "s2014e16", "season" => 2014, "number" => 16, "name" => "Kogoro in the Bar (Part 2)", "airdate" => "17 May 2014", "runtime" => 30, "rating" => null, "summary" => "Kogoro is undercover at the Blue Parrot, because Yuzuki Fukui asked him to investigate on a weird sound she hears frequently. Conan joins him, saying that Ran is angry because Kogoro is not home. But a simple investigation in a bar becomes more dramatic when…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/568091.jpg"),
        array("id" => "s2014e17", "season" => 2014, "number" => 17, "name" => "Bathroom Where Ran Collapsed as Well (Part 1)", "airdate" => "31 May 2014", "runtime" => 30, "rating" => null, "summary" => "As Conan and Ran are waiting for a meeting with Eri, they meet Sera, who is investigating Rumi Kitao's boyfriend, Kenya Settsu, about adultery.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/227/568092.jpg"),
