        array("id" => "s2025e5", "season" => 2025, "number" => 5, "name" => "Last Dance", "airdate" => "8 Feb 2025", "runtime" => 30, "rating" => null, "summary" => "Conan, Ran, and Sonoko are invited to a dance party. While changing into their dance shoes, a scream is heard.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/646/1615661.jpg"),
